import * as React from 'react'

import { cn } from '@/lib/utils'

function Card({
  className,
  size = 'default',
  ref,
  ...props
}: React.ComponentProps<'div'> & { size?: 'default' | 'sm' }) {
  return (
    <div
      ref={ref}
      data-slot='card'
      data-size={size}
      className={cn(
        'group/card flex flex-col gap-4 overflow-hidden rounded-md bg-card py-8 text-base/relaxed text-card-foreground ring-1 ring-foreground/10 has-[>img:first-child]:pt-0 data-[size=sm]:gap-3 data-[size=sm]:py-6 *:[img:first-child]:rounded-t-md *:[img:last-child]:rounded-b-md',
        className,
      )}
      {...props}
    />
  )
}

function CardHeader({ className, ref, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      ref={ref}
      data-slot='card-header'
      className={cn(
        'group/card-header @container/card-header grid auto-rows-min items-start gap-1 px-8 group-data-[size=sm]/card:px-6 has-data-[slot=card-action]:grid-cols-[1fr_auto] has-data-[slot=card-description]:grid-rows-[auto_auto] [.border-b]:pb-4 group-data-[size=sm]/card:[.border-b]:pb-3',
        className,
      )}
      {...props}
    />
  )
}

function CardTitle({ className, ref, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      ref={ref}
      data-slot='card-title'
      className={cn('font-heading text-2xl font-medium', className)}
      {...props}
    />
  )
}

function CardDescription({ className, ref, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      ref={ref}
      data-slot='card-description'
      className={cn('text-base/relaxed text-muted-foreground', className)}
      {...props}
    />
  )
}

function CardAction({ className, ref, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      ref={ref}
      data-slot='card-action'
      className={cn('col-start-2 row-span-2 row-start-1 self-start justify-self-end', className)}
      {...props}
    />
  )
}

function CardContent({ className, ref, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      ref={ref}
      data-slot='card-content'
      className={cn('px-8 group-data-[size=sm]/card:px-6', className)}
      {...props}
    />
  )
}

function CardFooter({ className, ref, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      ref={ref}
      data-slot='card-footer'
      className={cn(
        'flex items-center px-8 group-data-[size=sm]/card:px-6 [.border-t]:pt-4 group-data-[size=sm]/card:[.border-t]:pt-3',
        className,
      )}
      {...props}
    />
  )
}

export { Card, CardAction, CardContent, CardDescription, CardFooter, CardHeader, CardTitle }

// Derived prop types — exact component props for consumers wrapping these.
export type CardProps = React.ComponentProps<typeof Card>
export type CardHeaderProps = React.ComponentProps<typeof CardHeader>
export type CardTitleProps = React.ComponentProps<typeof CardTitle>
export type CardDescriptionProps = React.ComponentProps<typeof CardDescription>
export type CardActionProps = React.ComponentProps<typeof CardAction>
export type CardContentProps = React.ComponentProps<typeof CardContent>
export type CardFooterProps = React.ComponentProps<typeof CardFooter>

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/**
 * Resolves a cva variant prop to its default once, so the value fed to cva,
 * to the `data-*` attribute and to anything else that reads it agrees.
 *
 * cva reads an explicit `null` as "no variant" (no classes for that axis) but
 * `undefined` and `''` as "use `defaultVariants`", while `??` falls through
 * only for `null` and `undefined`. A component that wrote `data-color={color
 * ?? DEFAULT}` beside `variants({ color })` therefore advertised the default
 * with none of its classes for `null`, and `''` for `''`. `||` covers all
 * three, and every variant key here is a non-empty string, so a falsy value
 * is never a member.
 */
export function resolveVariant<T extends string>(value: T | null | undefined, fallback: T): T {
  return value || fallback
}
